import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as i,af as t}from"./chunks/mermaid.DrCHRkU0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const g=JSON.parse('{"title":"Claude Skills 深度解析","description":"","frontmatter":{},"headers":[],"relativePath":"zh/ai-tools/claude-skills-deep-dive.md","filePath":"zh/ai-tools/claude-skills-deep-dive.md","lastUpdated":1780924925000}'),s={name:"zh/ai-tools/claude-skills-deep-dive.md"};function o(n,l,r,d,h,c){return i(),e("div",null,[...l[0]||(l[0]=[t(`<h1 id="claude-skills-深度解析" tabindex="-1">Claude Skills 深度解析 <a class="header-anchor" href="#claude-skills-深度解析" aria-label="Permalink to &quot;Claude Skills 深度解析&quot;">​</a></h1><blockquote><p>学习来源: <a href="https://claude.com/blog/skills" target="_blank" rel="noreferrer">Introducing Agent Skills</a></p></blockquote><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>Skills 是 Claude 的能力扩展机制，通过文件夹（包含指令、脚本和资源）让 Claude 在特定任务上表现得更加专业。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="什么是-skills" tabindex="-1">什么是 Skills <a class="header-anchor" href="#什么是-skills" aria-label="Permalink to &quot;什么是 Skills&quot;">​</a></h3><p>Skills 本质上是<strong>定制化的 onboarding 材料</strong>，将专业知识打包，使 Claude 成为特定领域的专家。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传统方式: 每次对话都要重复背景信息</span></span>
<span class="line"><span>Skills 方式: 一次打包，持续复用</span></span></code></pre></div><h3 id="skills-的四大特性" tabindex="-1">Skills 的四大特性 <a class="header-anchor" href="#skills-的四大特性" aria-label="Permalink to &quot;Skills 的四大特性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>说明</th><th>价值</th></tr></thead><tbody><tr><td><strong>Composable</strong></td><td>可组合</td><td>多个 Skills 可自动协同，Claude 自动识别需要哪些</td></tr><tr><td><strong>Portable</strong></td><td>可移植</td><td>一次构建，多端使用（Claude Apps / Claude Code / API）</td></tr><tr><td><strong>Efficient</strong></td><td>高效</td><td>按需加载，只获取任务所需的最小信息</td></tr><tr><td><strong>Powerful</strong></td><td>强大</td><td>可包含可执行代码，处理传统编程更可靠的任务</td></tr></tbody></table><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><h3 id="自动匹配机制" tabindex="-1">自动匹配机制 <a class="header-anchor" href="#自动匹配机制" aria-label="Permalink to &quot;自动匹配机制&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户任务 → Claude 扫描可用 Skills → 匹配合适的 → 加载必要信息 → 执行</span></span></code></pre></div><p><strong>关键点</strong>：</p><ul><li>Claude 会自动判断任务与哪些 Skills 相关</li><li>匹配后只加载<strong>最小必要信息</strong>，保持速度</li><li>Skills 会出现在 Claude 的 chain of thought 中</li></ul><h3 id="与传统-plugin-的区别" tabindex="-1">与传统 Plugin 的区别 <a class="header-anchor" href="#与传统-plugin-的区别" aria-label="Permalink to &quot;与传统 Plugin 的区别&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>传统 Plugin</th><th>Skills</th></tr></thead><tbody><tr><td>加载方式</td><td>手动选择</td><td>自动匹配合</td></tr><tr><td>信息量</td><td>全部加载</td><td>按需最小加载</td></tr><tr><td>可组合性</td><td>有限</td><td>自动协调多个 Skills</td></tr><tr><td>代码执行</td><td>依赖外部</td><td>内置代码执行环境</td></tr></tbody></table><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><h3 id="_1-claude-apps" tabindex="-1">1. Claude Apps <a class="header-anchor" href="#_1-claude-apps" aria-label="Permalink to &quot;1. Claude Apps&quot;">​</a></h3><ul><li>Pro / Max / Team / Enterprise 用户可用</li><li>内置常见任务 Skills（文档创建、示例）</li><li>自动调用，无需手动选择</li><li>skill-creator Skill 可交互式引导创建</li></ul><h3 id="_2-claude-developer-platform-api" tabindex="-1">2. Claude Developer Platform (API) <a class="header-anchor" href="#_2-claude-developer-platform-api" aria-label="Permalink to &quot;2. Claude Developer Platform (API)&quot;">​</a></h3><ul><li>通过 <code>/v1/skills</code> 端点编程控制</li><li>需要 Code Execution Tool beta</li><li>支持版本管理和自定义</li></ul><p><strong>内置 Skills</strong>：</p><ul><li>Excel 专业表格（带公式）</li><li>PowerPoint 演示文稿</li><li>Word 文档</li><li>可填写 PDF</li></ul><h3 id="_3-claude-code" tabindex="-1">3. Claude Code <a class="header-anchor" href="#_3-claude-code" aria-label="Permalink to &quot;3. Claude Code&quot;">​</a></h3><ul><li>通过 anthropics/skills 市场插件安装</li><li>自动加载相关 Skills</li><li>通过版本控制共享团队 Skills</li><li>手动安装到 <code>~/.claude/skills</code></li></ul><h2 id="工程实践" tabindex="-1">工程实践 <a class="header-anchor" href="#工程实践" aria-label="Permalink to &quot;工程实践&quot;">​</a></h2><h3 id="skills-格式" tabindex="-1">Skills 格式 <a class="header-anchor" href="#skills-格式" aria-label="Permalink to &quot;Skills 格式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>skill-folder/</span></span>
<span class="line"><span>├── SKILL.md          # 核心定义文件</span></span>
<span class="line"><span>├── instructions/     # 指令文件</span></span>
<span class="line"><span>├── scripts/         # 可执行脚本</span></span>
<span class="line"><span>└── resources/       # 资源文件</span></span></code></pre></div><h3 id="创建流程" tabindex="-1">创建流程 <a class="header-anchor" href="#创建流程" aria-label="Permalink to &quot;创建流程&quot;">​</a></h3><ol><li>使用 skill-creator Skill（交互式引导）</li><li>Claude 询问工作流程</li><li>自动生成文件夹结构</li><li>格式化 SKILL.md</li><li>打包所需资源</li></ol><h3 id="安全考量" tabindex="-1">安全考量 <a class="header-anchor" href="#安全考量" aria-label="Permalink to &quot;安全考量&quot;">​</a></h3><blockquote><p>⚠️ Skills 可执行代码，只使用可信来源的 Skills</p></blockquote><ul><li>Code Execution Tool 提供安全执行环境</li><li>企业用户需管理员启用</li><li>个人用户可在设置中启用</li></ul><h2 id="企业级特性" tabindex="-1">企业级特性 <a class="header-anchor" href="#企业级特性" aria-label="Permalink to &quot;企业级特性&quot;">​</a></h2><h3 id="组织范围管理" tabindex="-1">组织范围管理 <a class="header-anchor" href="#组织范围管理" aria-label="Permalink to &quot;组织范围管理&quot;">​</a></h3><ul><li>Organization-wide Skills 部署</li><li>管理员控制可用 Skills</li><li>团队级别的一致性</li></ul><h3 id="合作伙伴生态" tabindex="-1">合作伙伴生态 <a class="header-anchor" href="#合作伙伴生态" aria-label="Permalink to &quot;合作伙伴生态&quot;">​</a></h3><ul><li>Canva: 定制设计 Agents</li><li>Notion: 简化工作流</li><li>Box: 企业内容处理</li></ul><h2 id="与-agentic-engineering-的关系" tabindex="-1">与 Agentic Engineering 的关系 <a class="header-anchor" href="#与-agentic-engineering-的关系" aria-label="Permalink to &quot;与 Agentic Engineering 的关系&quot;">​</a></h2><p>Skills 是 Agentic Engineering 的重要组成部分：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agentic Engineering = Tools + Loop + Goal + Skills</span></span>
<span class="line"><span>                                         ↑</span></span>
<span class="line"><span>                              专业化能力扩展</span></span></code></pre></div><p>Skills 让我们能够：</p><ul><li><strong>封装专业知识</strong>：将领域专家的工作方式代码化</li><li><strong>保持一致性</strong>：团队成员共享相同的处理方式</li><li><strong>持续演进</strong>：Skills 可版本控制和升级</li></ul><h2 id="参考资源" tabindex="-1">参考资源 <a class="header-anchor" href="#参考资源" aria-label="Permalink to &quot;参考资源&quot;">​</a></h2><ul><li><a href="https://docs.anthropic.com/en/docs/agents-and-tools/agent-skills/overview" target="_blank" rel="noreferrer">官方文档</a></li><li><a href="https://platform.claude.com/cookbook/skills-notebooks-01-skills-introduction" target="_blank" rel="noreferrer">Skills Cookbook</a></li><li><a href="https://github.com/anthropics/skills" target="_blank" rel="noreferrer">GitHub 示例</a></li><li><a href="https://www.anthropic.com/engineering/equipping-agents-for-the-real-world-with-agent-skills" target="_blank" rel="noreferrer">工程博客</a></li></ul><h2 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h2><ul><li>2026-04-12: 初始化文档</li></ul>`,48)])])}const m=a(s,[["render",o]]);export{g as __pageData,m as default};
